const perro = {
  nombre: "Rex",
  ladrar() {
    return this.nombre + " dice guau";
  },
};
console.log(perro.ladrar());

class Contador {
  constructor() {
    this.valor = 0;
  }
  sumar() {
    this.valor++;
    return this.valor;
  }
}
const c = new Contador();
console.log(c.sumar());
const sumar = c.sumar;
console.log(sumar());

class Equipo {
  constructor() {
    this.nombre = "Front";
    this.miembros = ["Ana", "Luis"];
  }
  listar() {
    return this.miembros.map((m) => m + "@" + this.nombre).join(",");
  }
}
console.log(new Equipo().listar());

class Boton {
  constructor(texto) {
    this.texto = texto;
  }
  click() {
    return "Clic en " + this.texto;
  }
}
const b = new Boton("Guardar");
const conBind = b.click.bind(b);
const otro = { texto: "Cancelar", click: conBind };
console.log(otro.click());

function presentar(saludo, signo) {
  return saludo + ", soy " + this.nombre + signo;
}
const ana = { nombre: "Ana" };
console.log(presentar.call(ana, "Hola", "!"));
console.log(presentar.apply(ana, ["Hey", "?"]));

class Rectangulo {
  constructor(ancho, alto) {
    this.ancho = ancho;
    this.alto = alto;
  }
  get area() {
    return this.ancho * this.alto;
  }
}
const r = new Rectangulo(2, 3);
r.ancho = 10;
console.log(r.area);
console.log(typeof r.area);

class Animal {
  constructor(nombre) {
    this.nombre = nombre;
  }
  hablar() {
    return this.nombre + " hace un sonido";
  }
}
class Gato extends Animal {
  hablar() {
    return super.hablar() + " y maúlla";
  }
}
const g = new Gato("Michi");
console.log(g.hablar());
console.log(g instanceof Animal);

class Temporizador {
  segundos = 0;
  tickFlecha = () => {
    this.segundos++;
  };
  tickNormal() {
    this.segundos++;
  }
}
const t = new Temporizador();
const { tickFlecha, tickNormal } = t;
tickFlecha();
tickFlecha();
console.log(t.segundos);
tickNormal();
console.log(t.segundos);
